#!/usr/bin/env python3
"""Refit V_reach against V03 labels generated by the direct V84 V04 proposal."""

from __future__ import annotations

import argparse
import importlib.util
import json
import random
import struct
import sys
from pathlib import Path
from typing import Any

import numpy as np

PROPOSAL_DIR = Path(__file__).resolve().parents[1]
V02_DIR = PROPOSAL_DIR / "v02"
V04_DIR = Path(__file__).resolve().parent
sys.path.insert(0, str(PROPOSAL_DIR))
sys.path.insert(0, str(V02_DIR))
sys.path.insert(0, str(V04_DIR))

RUNTIME_PATH = V04_DIR / "refit_vreach_runtime_v01.py"
RUNTIME_SPEC = importlib.util.spec_from_file_location("r1_v04_v84_runtime_refit_helpers", RUNTIME_PATH)
if RUNTIME_SPEC is None or RUNTIME_SPEC.loader is None:
    raise ImportError(f"could not load V03 runtime refit helpers from {RUNTIME_PATH}")
RUNTIME = importlib.util.module_from_spec(RUNTIME_SPEC)
sys.modules[RUNTIME_SPEC.name] = RUNTIME
RUNTIME_SPEC.loader.exec_module(RUNTIME)

REQUESTS = RUNTIME.REQUESTS
REFIT = RUNTIME.REFIT
HELPERS = RUNTIME.HELPERS

V84_PROPOSAL_SHA256 = "3ce84b1e4f44f7713c80999223d5638b8ada0eeffea00a06f787de9dc0616f33"
V84_POLICY_IDENTITY_SHA256 = "3525d5f1c5d09a9a6e0e5dd2e19b5bfbb8694ee904d94aff186670071c6d10ee"
V84_TEMPERATURE = 0.17864354564164298
V84_TEMPERATURE_BITS_LE_HEX = "3c0f16adcaddc63f"
V84_LABEL_RECEIPT_SHA256 = "9c74658d86e2d492179c262d12fbf3aa4272402dd90015f94a8d9412ad529ea1"
V84_LABELS_SHA256 = "cecc7c4a0c5a9d99f935c0da0f8923c1a268af6025ed7e7727e243071eefdeea"
V84_TRACES_SHA256 = "a35bb65e1bd27c8c6557836268855cf5458440b5dd15ff3e324ffc9d19638b86"
V84_REPLAY_COMPARISON_SCHEMA = "FAS_R1_V84_V03_REPLAY_COMPARISON_V01"
V84_REPLAY_COMPARISON_SHA256 = "2f834140ab471df555113bd3fccaf5c95eff935670c3ee83efc71e49d42a7574"
V84_TEMPERATURE_OVERRIDE_SCHEMA = "FAS_R1_V84_RUNTIME_TEMPERATURE_ENGINEERING_OVERRIDE_V01"
V19_HISTORICAL_QUALIFICATION_RUNS = [f"V{version}" for version in range(110, 118)]
V19_QUALIFICATION_MANIFEST_SHA256 = {
    "V110": "1ec2a45f2b67ea994b0bfe7ac38ac8e1342b5d936d420c27d001aae7ec113f4e",
    "V114": "f1a0f6040510951a51eb5eeba35a37804a69b50902ec03a7a5508fa371f4acda",
}
RECEIPT_SCHEMA = "FAS_R1_VREACH_V84_DIRECT_RUNTIME_REFIT_V01"
RECEIPT_STATUS = "VREACH_V84_DIRECT_RUNTIME_REFIT_COMPLETE"
WEIGHTS_NAME = "v-reach-weights-v84-lowtemp-runtime-v01.json"
HISTORY_NAME = "training-history-v84-lowtemp-runtime-v01.json"
RECEIPT_NAME = "vreach-v84-lowtemp-runtime-refit-receipt-v01.json"
FAILURE_NAME = "failure-v84-lowtemp-runtime-refit-v01.json"


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--world-dir", type=Path, required=True)
    parser.add_argument("--sensor-dir", type=Path, required=True)
    parser.add_argument("--labels", type=Path, required=True)
    parser.add_argument("--traces", type=Path, required=True)
    parser.add_argument("--label-receipt", type=Path, required=True)
    parser.add_argument("--start-states", type=Path, required=True)
    parser.add_argument("--start-receipt", type=Path, required=True)
    parser.add_argument("--request-receipt", type=Path, required=True)
    parser.add_argument("--proposal-weights", type=Path, required=True)
    parser.add_argument("--proposal-fit-receipt", type=Path, required=True)
    parser.add_argument("--temperature-override", type=Path, required=True)
    parser.add_argument("--replay-comparison", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--h-scale", type=float, default=0.1)
    parser.add_argument("--seed", type=int, default=20260926)
    parser.add_argument("--epochs", type=int, default=100)
    parser.add_argument("--device", choices=("auto", "cpu", "cuda"), default="auto")
    return parser.parse_args()


def validate_v84_proposal_sha256(value: Any) -> str:
    digest = RUNTIME._valid_sha256(value, "V84 proposal SHA")
    if digest != V84_PROPOSAL_SHA256:
        raise ValueError("proposal SHA is not the pinned direct V84 V04 checkpoint")
    return digest


def validate_v84_request_proposal_sha(request_receipt: dict[str, Any]) -> str:
    return validate_v84_proposal_sha256(RUNTIME.get_request_proposal_sha256(request_receipt))


def validate_v84_temperature_override(
    override: Any, override_path: Path, current_proposal_sha256: str
) -> float:
    if not isinstance(override, dict):
        raise ValueError("V84 temperature override must be a JSON object")
    if override.get("schema") != V84_TEMPERATURE_OVERRIDE_SCHEMA:
        raise ValueError("V84 temperature override has an unsupported schema")
    if override.get("status") != "COMPLETE":
        raise ValueError("V84 temperature override is not COMPLETE")
    if override.get("mode") != "ADAPTIVE_ENGINEERING":
        raise ValueError("V84 temperature override is not ADAPTIVE_ENGINEERING")
    if override.get("qualification_selection_access") is not True:
        raise ValueError("V84 temperature override must disclose qualification selection access")
    if override.get("scientific_confirmation_eligible") is not False:
        raise ValueError("V84 temperature override must remain scientifically ineligible")
    proposal_sha256 = validate_v84_proposal_sha256(current_proposal_sha256)
    if override.get("proposal_sha256") != proposal_sha256:
        raise ValueError("V84 temperature override does not bind the direct V84 proposal SHA")
    selected_temperature = override.get("selected_temperature")
    if isinstance(selected_temperature, bool) or not isinstance(selected_temperature, (int, float)):
        raise ValueError("V84 temperature override selected value must be a JSON number")
    temperature = float(selected_temperature)
    if temperature != V84_TEMPERATURE:
        raise ValueError("V84 temperature override selected value differs from the pinned temperature")
    expected_bits = struct.pack("<d", V84_TEMPERATURE).hex()
    if (
        override.get("selected_temperature_f64_bits_le_hex") != V84_TEMPERATURE_BITS_LE_HEX
        or override.get("selected_temperature_f64_bits_le_hex") != expected_bits
    ):
        raise ValueError("V84 temperature override f64 bits differ from the pinned temperature")

    lineage = override.get("source_lineage")
    if not isinstance(lineage, dict):
        raise ValueError("V84 temperature override is missing historical source lineage")
    if lineage.get("temperature_source") != "V19":
        raise ValueError("V84 temperature override does not identify the V19 temperature source")
    if lineage.get("historical_qualification_selection_access") is not True:
        raise ValueError("V84 override lineage omits historical qualification-selection disclosure")
    if lineage.get("historical_qualification_runs") != V19_HISTORICAL_QUALIFICATION_RUNS:
        raise ValueError("V84 override lineage must identify the V110-V117 qualification history")
    if lineage.get("qualification_manifest_sha256") != V19_QUALIFICATION_MANIFEST_SHA256:
        raise ValueError("V84 override lineage does not bind the V110 and V114 manifests")
    if lineage.get("proposal_id") != "V84" or lineage.get("proposal_sha256") != proposal_sha256:
        raise ValueError("V84 override lineage does not bind the direct V84 proposal")
    override_path.resolve(strict=True)
    return temperature


def validate_v84_label_artifact_hashes(
    label_receipt_path: Path, labels_path: Path, traces_path: Path
) -> dict[str, str]:
    observed = {
        "simulator_receipt_sha256": RUNTIME.sha(label_receipt_path),
        "labels_sha256": RUNTIME.sha(labels_path),
        "traces_sha256": RUNTIME.sha(traces_path),
    }
    expected = {
        "simulator_receipt_sha256": V84_LABEL_RECEIPT_SHA256,
        "labels_sha256": V84_LABELS_SHA256,
        "traces_sha256": V84_TRACES_SHA256,
    }
    if observed != expected:
        raise ValueError("V84 V167 label/simulator artifacts differ from the pinned exact-string run")
    return observed


def validate_v84_replay_comparison(
    comparison: Any,
    comparison_path: Path,
    comparison_sha256: str,
) -> dict[str, Any]:
    """Validate the sealed V169 replay record against the exact V167 label lineage."""
    if not isinstance(comparison, dict):
        raise ValueError("V84 replay comparison must be a JSON object")
    if comparison.get("schema") != V84_REPLAY_COMPARISON_SCHEMA:
        raise ValueError("V84 replay comparison has an unsupported schema")
    if comparison.get("status") != "COMPLETE":
        raise ValueError("V84 replay comparison is not COMPLETE")
    if comparison.get("exact_replay") is not True:
        raise ValueError("V84 replay comparison does not confirm exact replay")
    if comparison.get("scientific_confirmation_eligible") is not False:
        raise ValueError("V84 replay comparison must remain scientifically ineligible")
    expected_fields = {
        "temperature_f64_bits_le_hex": V84_TEMPERATURE_BITS_LE_HEX,
        "policy_identity_sha256": V84_POLICY_IDENTITY_SHA256,
        "raw_proposal_sha256": V84_PROPOSAL_SHA256,
        "labels_sha256": V84_LABELS_SHA256,
        "traces_sha256": V84_TRACES_SHA256,
    }
    for field, expected in expected_fields.items():
        if comparison.get(field) != expected:
            raise ValueError(f"V84 replay comparison has the wrong {field}")
    receipt_hashes = comparison.get("receipt_sha256")
    if not isinstance(receipt_hashes, dict) or receipt_hashes.get("v167") != V84_LABEL_RECEIPT_SHA256:
        raise ValueError("V84 replay comparison does not bind the V167 simulator receipt")
    path = comparison_path.resolve(strict=True)
    observed_sha256 = RUNTIME._valid_sha256(comparison_sha256, "V169 replay-comparison SHA")
    if observed_sha256 != V84_REPLAY_COMPARISON_SHA256:
        raise ValueError("V84 replay comparison differs from the sealed V169 artifact")
    return {
        "path": str(path),
        "schema": V84_REPLAY_COMPARISON_SCHEMA,
        "sha256": observed_sha256,
        "bytes": path.stat().st_size,
        "contents": comparison,
    }


def build_v84_policy_identity(
    source_hashes: dict[str, str] | None = None,
) -> tuple[dict[str, Any], str]:
    pinned_sources = source_hashes or RUNTIME._expected_policy_source_hashes()
    identity_sha256 = RUNTIME._policy_identity_digest(
        V84_PROPOSAL_SHA256,
        RUNTIME.V03_MIXTURE_ID,
        V84_TEMPERATURE,
        RUNTIME.V03_SIMULATOR_VERSION,
        pinned_sources,
    )
    identity = {
        "schema": RUNTIME.V03_IDENTITY_SCHEMA,
        "sha256": identity_sha256,
        "weights_sha256": V84_PROPOSAL_SHA256,
        "mixture_id": RUNTIME.V03_MIXTURE_ID,
        "temperature": V84_TEMPERATURE,
        "temperature_f64_bits_le_hex": V84_TEMPERATURE_BITS_LE_HEX,
        "simulator_version": RUNTIME.V03_SIMULATOR_VERSION,
        "source_sha256": pinned_sources,
    }
    if source_hashes is None and identity_sha256 != V84_POLICY_IDENTITY_SHA256:
        raise ValueError("pinned V03 source files do not produce the exact V84 policy identity")
    return identity, identity_sha256


def validate_v84_request_start_fit_lineage(
    request_receipt: dict[str, Any],
    start_states_path: Path,
    start_receipt_path: Path,
    proposal_weights_path: Path,
    proposal_fit_receipt_path: Path,
) -> dict[str, Any]:
    """Bind the frozen V04 request/start artifacts directly to the V84 proposal fit."""
    proposal_sha256 = validate_v84_proposal_sha256(RUNTIME.sha(proposal_weights_path))
    proposal_weights = REQUESTS.verify_proposal_weights(proposal_weights_path)
    if proposal_weights.get("schema") != REQUESTS.PROPOSAL_SCHEMA:
        raise ValueError("V84 proposal weights have an unsupported V04 schema")

    request_proposal_sha256 = validate_v84_request_proposal_sha(request_receipt)
    if request_proposal_sha256 != proposal_sha256:
        raise ValueError("V04 request receipt does not bind the supplied V84 checkpoint")
    start_sha256 = RUNTIME.sha(start_states_path)
    proposal_lineage, request_inputs = REFIT.validate_request_receipt(
        request_receipt, proposal_sha256, start_sha256
    )

    proposal_record = RUNTIME._require_file_record(
        request_inputs.get("proposal_weights"), proposal_weights_path, "V84 proposal weights"
    )
    private_path = Path(request_inputs["private_trainval_only"]["path"]).resolve(strict=True)
    private_record = RUNTIME._require_file_record(
        request_inputs.get("private_trainval_only"), private_path, "V04 private train/validation sidecar"
    )
    private_rows = list(REQUESTS.iter_jsonl(private_path))
    if len(private_rows) != REQUESTS.TRAIN_VALIDATION_COUNT:
        raise ValueError("V84 proposal fit sidecar must contain exactly the 64/16 train-validation roster")

    fit_receipt_record = RUNTIME._require_file_record(
        request_inputs.get("proposal_fit_receipt"),
        proposal_fit_receipt_path,
        "direct V84 V04 proposal-fit receipt",
    )
    proposal_fit_receipt = json.loads(proposal_fit_receipt_path.read_text(encoding="utf-8"))
    verified_proposal_lineage = REQUESTS.verify_proposal_receipt(
        proposal_fit_receipt,
        proposal_record,
        proposal_sha256,
        private_record,
        len(private_rows),
    )
    if verified_proposal_lineage.get("identity_receipt_sha256") != proposal_lineage.get(
        "identity_receipt_sha256"
    ):
        raise ValueError("V04 request identity lineage differs from the direct V84 fit receipt")

    start_record = RUNTIME._require_file_record(
        request_inputs.get("start_states"), start_states_path, "V04 start states"
    )
    start_receipt_record = RUNTIME._require_file_record(
        request_inputs.get("start_state_receipt"),
        start_receipt_path,
        "V04 start-state receipt",
    )
    start_receipt = json.loads(start_receipt_path.read_text(encoding="utf-8"))
    REQUESTS.verify_start_receipt(
        start_receipt,
        start_record["sha256"],
        private_record["sha256"],
        fit_receipt_record["sha256"],
    )
    request_record = RUNTIME._require_file_record(
        request_receipt.get("request_file"),
        Path(request_receipt["request_file"]["path"]),
        "V04 V_reach request file",
    )
    return {
        "proposal_sha256": proposal_sha256,
        "proposal_weights": proposal_weights,
        "proposal_lineage": verified_proposal_lineage,
        "proposal_record": proposal_record,
        "proposal_fit_receipt_record": fit_receipt_record,
        "proposal_fit_receipt": proposal_fit_receipt,
        "private_trainval_record": private_record,
        "private_trainval_path": private_path,
        "private_trainval_rows": len(private_rows),
        "start_record": start_record,
        "start_receipt_record": start_receipt_record,
        "start_receipt": start_receipt,
        "request_record": request_record,
        "request_inputs": request_inputs,
    }


def main() -> int:
    args = parse_args()
    output = args.output.resolve()
    if output.exists():
        raise FileExistsError(f"refusing to overwrite {output}")
    if not 0.01 <= args.h_scale <= 1.0 or args.epochs <= 0:
        raise ValueError("H scale must be in [0.01, 1] and epochs must be positive")
    output.mkdir(parents=True)
    try:
        world_dir = args.world_dir.resolve(strict=True)
        sensor_dir = args.sensor_dir.resolve(strict=True)
        labels_path = args.labels.resolve(strict=True)
        traces_path = args.traces.resolve(strict=True)
        label_receipt_path = args.label_receipt.resolve(strict=True)
        start_states_path = args.start_states.resolve(strict=True)
        start_receipt_path = args.start_receipt.resolve(strict=True)
        request_receipt_path = args.request_receipt.resolve(strict=True)
        proposal_weights_path = args.proposal_weights.resolve(strict=True)
        proposal_fit_receipt_path = args.proposal_fit_receipt.resolve(strict=True)
        temperature_override_path = args.temperature_override.resolve(strict=True)
        replay_comparison_path = args.replay_comparison.resolve(strict=True)
        public_path = world_dir / "public-tasks.jsonl"
        support_path = world_dir / REQUESTS.SUPPORT_FILENAME

        public_rows = RUNTIME.read_jsonl(public_path)
        support = json.loads(support_path.read_text(encoding="utf-8"))
        public, split_by_task = REQUESTS.validate_split_roster(public_rows, support)
        train_tasks = {task_id for task_id, split in split_by_task.items() if split == "train"}
        validation_tasks = {
            task_id for task_id, split in split_by_task.items() if split == "validation"
        }
        trainval_tasks = train_tasks | validation_tasks
        if (len(train_tasks), len(validation_tasks), len(trainval_tasks)) != (64, 16, 80):
            raise ValueError("V04 fit roster must contain exactly 64 train and 16 validation tasks")

        request_receipt = json.loads(request_receipt_path.read_text(encoding="utf-8"))
        lineage = validate_v84_request_start_fit_lineage(
            request_receipt,
            start_states_path,
            start_receipt_path,
            proposal_weights_path,
            proposal_fit_receipt_path,
        )
        temperature_override = json.loads(
            temperature_override_path.read_text(encoding="utf-8")
        )
        temperature = validate_v84_temperature_override(
            temperature_override,
            temperature_override_path,
            lineage["proposal_sha256"],
        )
        temperature_override_record = RUNTIME.file_record(temperature_override_path)
        replay_comparison = json.loads(replay_comparison_path.read_text(encoding="utf-8"))
        replay_comparison_record = validate_v84_replay_comparison(
            replay_comparison,
            replay_comparison_path,
            RUNTIME.sha(replay_comparison_path),
        )
        inputs = lineage["request_inputs"]
        for key, path, label in (
            ("public_tasks", public_path, "public-task file"),
            ("support_manifest", support_path, "support manifest"),
            ("sensor_receipt", sensor_dir / "receipt.json", "sensor receipt"),
        ):
            RUNTIME._require_file_record(inputs.get(key), path, f"V04 request {label}")
        if inputs.get("identity_model", {}).get("sha256") != REQUESTS.IDENTITY_SHA256:
            raise ValueError("V04 request does not bind the pinned identity head")

        start_rows = RUNTIME.read_jsonl(start_states_path)
        grouped_starts = REQUESTS.validate_start_rows(start_rows, public, split_by_task)
        if set(grouped_starts) != trainval_tasks:
            raise ValueError("V04 starts do not cover exactly the train/validation roster")

        policy_identity, policy_identity_sha256 = build_v84_policy_identity()
        if temperature != policy_identity["temperature"]:
            raise ValueError("V84 override temperature differs from computed V03 policy identity")
        source_hashes = policy_identity["source_sha256"]
        label_artifact_hashes = validate_v84_label_artifact_hashes(
            label_receipt_path, labels_path, traces_path
        )
        label_receipt = json.loads(label_receipt_path.read_text(encoding="utf-8"))
        label_contract = RUNTIME.validate_v03_simulator_receipt(
            label_receipt,
            labels_path,
            traces_path,
            Path(lineage["request_record"]["path"]),
            proposal_weights_path,
            V84_PROPOSAL_SHA256,
            policy_identity_sha256,
            V84_TEMPERATURE,
            expected_source_hashes=source_hashes,
            expected_tasks=len(trainval_tasks),
        )
        if label_contract["policy_identity"] != policy_identity:
            raise ValueError("V03 labels were not generated by the direct V84 low-temperature policy")
        expected_rollouts = int(request_receipt["rollouts_per_state"])
        if label_contract["rollout_count"] != label_contract["state_count"] * expected_rollouts:
            raise ValueError("V03 simulator rollout totals differ from the V04 request receipt")
        label_counts = RUNTIME.validate_v03_label_rows(
            labels_path,
            trainval_tasks,
            split_by_task,
            V84_PROPOSAL_SHA256,
            policy_identity_sha256,
            policy_identity,
            label_contract["state_count"],
            label_contract["rollout_count"],
        )

        feature_store = RUNTIME.load_feature_store(sensor_dir, public_path, public_rows, support_path)
        x, y, splits, metadata = HELPERS.PIPELINE.assemble_vreach(
            labels_path, feature_store, max_budget=RUNTIME.MAX_BUDGET
        )
        if set(splits) != {"train", "validation"}:
            raise ValueError(f"V84 fit requires train and validation labels only; got {set(splits)}")
        if any(row["split"] == "qualification" for row in metadata):
            raise ValueError("qualification V_reach targets entered the V84 fit dataset")
        observed_tasks_by_split = {
            name: {row["task_id"] for row in metadata if row["split"] == name}
            for name in ("train", "validation")
        }
        if observed_tasks_by_split != {"train": train_tasks, "validation": validation_tasks}:
            raise ValueError("assembled V_reach labels differ from the exact V04 64/16 task split")

        scaled_x = HELPERS.scale_h_groups(x, args.h_scale)
        import torch

        torch.set_num_threads(1)
        torch.use_deterministic_algorithms(True)
        random.seed(args.seed)
        np.random.seed(args.seed)
        torch.manual_seed(args.seed)
        device_name = "cuda" if args.device == "auto" and torch.cuda.is_available() else args.device
        device = torch.device("cpu" if device_name == "auto" else device_name)
        train_mask = splits == "train"
        validation_mask = splits == "validation"
        model, history, best_epoch = HELPERS.fit_scaled(
            scaled_x, y, splits, args.seed + 1, args.epochs, torch, device
        )
        probabilities = RUNTIME.predict_value(model, scaled_x, device)
        metrics = {
            "train": RUNTIME.binary_metrics(probabilities[train_mask], y[train_mask]),
            "validation": RUNTIME.binary_metrics(
                probabilities[validation_mask], y[validation_mask]
            ),
        }
        weights_path = output / WEIGHTS_NAME
        weights_sha256 = RUNTIME.export_v07(
            model,
            args.h_scale,
            V84_PROPOSAL_SHA256,
            policy_identity_sha256,
            weights_path,
        )
        history_path = output / HISTORY_NAME
        history_path.write_text(
            json.dumps(history, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )

        request_file_path = Path(lineage["request_record"]["path"])
        source_paths = [
            Path(__file__).resolve(),
            RUNTIME_PATH.resolve(),
            Path(REFIT.__file__).resolve(),
            Path(HELPERS.__file__).resolve(),
            RUNTIME.PIPELINE_PATH.resolve(),
            (PROPOSAL_DIR / "feature_math.py").resolve(),
            (V02_DIR / "value_training.py").resolve(),
            *[(PROPOSAL_DIR.parent / relative).resolve() for relative in RUNTIME.POLICY_IDENTITY_SOURCE_FILES.values()],
            public_path,
            support_path,
            sensor_dir / "receipt.json",
            sensor_dir / "constraint_H.float32.npy",
            sensor_dir / "global_h.float32.npy",
            sensor_dir / "rows.jsonl",
            labels_path,
            traces_path,
            label_receipt_path,
            start_states_path,
            start_receipt_path,
            request_receipt_path,
            request_file_path,
            lineage["private_trainval_path"],
            proposal_weights_path,
            proposal_fit_receipt_path,
            temperature_override_path,
            replay_comparison_path,
        ]
        input_pins = {
            str(path.resolve(strict=True)): {
                "sha256": RUNTIME.sha(path),
                "bytes": path.stat().st_size,
            }
            for path in dict.fromkeys(source_paths)
        }
        train_rows = int(train_mask.sum())
        validation_rows = int(validation_mask.sum())
        receipt = {
            "schema": RECEIPT_SCHEMA,
            "status": RECEIPT_STATUS,
            "mode": "adaptive engineering refit; direct V84 V04 proposal with V03 train/validation labels only",
            "analysis_mode": "ADAPTIVE_ENGINEERING",
            "qualification_previously_opened": True,
            "scientific_confirmation_eligible": False,
            "qualification_targets_consumed": False,
            "qualification_features_used_for_fit": False,
            "proposal_refit": False,
            "proposal_lineage": {
                "source": "direct V04 proposal fit V84",
                "weights_sha256": V84_PROPOSAL_SHA256,
                "proposal_fit_receipt_sha256": lineage["proposal_fit_receipt_record"]["sha256"],
                "request_bound_proposal_sha256": validate_v84_request_proposal_sha(request_receipt),
            },
            "runtime_policy": {
                "proposal_weights_sha256": V84_PROPOSAL_SHA256,
                "proposal_fit_receipt_sha256": lineage["proposal_fit_receipt_record"]["sha256"],
                "mixture_id": RUNTIME.V03_MIXTURE_ID,
                "temperature": V84_TEMPERATURE,
                "temperature_f64_bits_le_hex": V84_TEMPERATURE_BITS_LE_HEX,
                "temperature_lineage": "V19 engineering low-temperature setting reused in the V84 qualification pilot V161-V164; prior qualification access is disclosed",
                "policy_identity_sha256": policy_identity_sha256,
                "policy_identity": policy_identity,
                "temperature_override": {
                    "artifact_file": temperature_override_path.name,
                    "schema": temperature_override["schema"],
                    "sha256": temperature_override_record["sha256"],
                    "bytes": temperature_override_record["bytes"],
                    "selected_temperature": temperature,
                    "contents": temperature_override,
                },
                "temperature_tuning_provenance": {
                    "source": temperature_override["source_lineage"]["temperature_source"],
                    "qualification_selection_access": temperature_override[
                        "source_lineage"
                    ]["historical_qualification_selection_access"],
                    "historical_qualification_runs": temperature_override[
                        "source_lineage"
                    ]["historical_qualification_runs"],
                    "qualification_manifest_sha256": temperature_override[
                        "source_lineage"
                    ]["qualification_manifest_sha256"],
                },
            },
            "request_start_provenance": {
                "request_receipt_schema": request_receipt.get("schema"),
                "request_receipt_sha256": RUNTIME.sha(request_receipt_path),
                "request_file_sha256": lineage["request_record"]["sha256"],
                "request_proposal_sha256": V84_PROPOSAL_SHA256,
                "start_states_sha256": lineage["start_record"]["sha256"],
                "start_state_receipt_sha256": lineage["start_receipt_record"]["sha256"],
                "proposal_fit_receipt_sha256": lineage["proposal_fit_receipt_record"]["sha256"],
            },
            "label_generation": {
                "simulator_receipt_schema": label_receipt.get("schema"),
                **label_artifact_hashes,
                "dataset_schema": RUNTIME.V03_LABEL_SCHEMA,
                "state_schema": RUNTIME.V03_STATE_SCHEMA,
                "labels_sha256": label_contract["label_file"]["sha256"],
                "traces_sha256": label_contract["trace_file"]["sha256"],
                "task_count": label_counts["task_count"],
                "state_count": label_counts["state_count"],
                "rollout_count": label_counts["rollout_count"],
            },
            "replay_comparison": {
                "artifact_file": replay_comparison_path.name,
                **replay_comparison_record,
            },
            "dataset": {
                "world_split_counts": support["split_counts"],
                "label_sha256": RUNTIME.sha(labels_path),
                "task_counts": {"train": len(train_tasks), "validation": len(validation_tasks)},
                "state_rows": int(len(metadata)),
                "train_rows": train_rows,
                "validation_rows": validation_rows,
                "qualification_rows": 0,
                "rollout_rows": int(sum(row["rollouts"] for row in metadata)),
            },
            "identity_sha256": REQUESTS.IDENTITY_SHA256,
            "v07_runtime_v01": {
                "weights_file": weights_path.name,
                "weights_sha256": weights_sha256,
                "h_input_scale": args.h_scale,
                "budget_normalization_max": RUNTIME.MAX_BUDGET,
                "best_epoch": best_epoch,
                "metrics": metrics,
                "train_forecast_quantiles": RUNTIME.output_quantiles(probabilities[train_mask]),
                "validation_forecast_quantiles": RUNTIME.output_quantiles(
                    probabilities[validation_mask]
                ),
            },
            "training": {
                "seed": args.seed + 1,
                "optimizer": "AdamW",
                "learning_rate": 1e-3,
                "weight_decay": 1e-4,
                "max_epochs": args.epochs,
                "early_stopping_patience": 10,
                "device": str(device),
            },
            "input_pins": input_pins,
        }
        receipt_path = output / RECEIPT_NAME
        receipt_path.write_text(
            json.dumps(receipt, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
        print(f"proposal_sha256={V84_PROPOSAL_SHA256}")
        print(f"proposal_policy_identity_sha256={policy_identity_sha256}")
        print(f"best_epoch={best_epoch}")
        print(f"validation_metrics={json.dumps(metrics['validation'], sort_keys=True)}")
        print(f"receipt_sha256={RUNTIME.sha(receipt_path)}")
        return 0
    except Exception as error:
        failure = {
            "schema": "FAS_R1_VREACH_V84_DIRECT_RUNTIME_REFIT_FAILURE_V01",
            "status": "VREACH_V84_DIRECT_RUNTIME_REFIT_FAILED",
            "analysis_mode": "ADAPTIVE_ENGINEERING",
            "qualification_previously_opened": True,
            "scientific_confirmation_eligible": False,
            "error": str(error),
        }
        (output / FAILURE_NAME).write_text(
            json.dumps(failure, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
        raise


if __name__ == "__main__":
    raise SystemExit(main())
